import math

state = 'REVERSE'
look_dir = -64.0
look_timer = 0

def control(obs):
    global state, look_dir, look_timer

    hold_s = obs.get('motion', {}).get('hold_s', 0.0)
    hitch = obs.get('hitch_deg', 0.0)
    status = obs.get('status', '')
    steer_actual = obs.get('steer_deg', 0.0)

    look_timer += 1
    if look_timer > 35:
        look_timer = 0
        look_dir = -64.0 if look_dir == 64.0 else 64.0
    look_deg = look_dir

    if hold_s > 0.05:
        return (-30.0, 0.0, look_deg)

    views = obs.get('views', {})
    left_dists = []
    right_dists = []
    front_left_dist = 999.0

    for vname, vdata in views.items():
        if not vdata:
            continue
        ox, oy = vdata.get('origin', [0, 0])
        walls = vdata.get('walls', [])
        for b_deg, dist in walls:
            rad = math.radians(b_deg)
            px = ox + dist * math.cos(rad)
            py = oy + dist * math.sin(rad)

            if px > 0.5 and py > 0:
                d = math.hypot(px, py)
                if d < front_left_dist:
                    front_left_dist = d

            if -10.0 <= px <= -1.0:
                if py > 0:
                    left_dists.append(py)
                else:
                    right_dists.append(-py)

    min_l = min(left_dists) if left_dists else 3.0
    min_r = min(right_dists) if right_dists else 3.0

    target_hitch = 6.0
    if min_r < 1.9:
        target_hitch = 10.0
    elif min_l < 1.9:
        target_hitch = -4.0
    else:
        diff = min_l - min_r
        target_hitch = max(min(diff * 4.0, 10.0), -8.0)

    err = hitch - target_hitch
    steer = err * 2.2

    if front_left_dist < 1.6:
        steer = min(steer, -20.0)

    steer = max(min(steer, 40.0), -40.0)
    speed = -0.5

    return (steer, speed, look_deg)

