fwd_ticks = 0
look_dir = -64.0

def control(obs):
    global state, fwd_ticks, look_dir

    hold_s = obs.get('motion', {}).get('hold_s', 0.0)
    hitch = obs.get('hitch_deg', 0.0)
    status = obs.get('status', '')

    look_deg = -64.0

    if hold_s > 0.05:
        return (0.0, 0.0, look_deg)

    if state == 'UNPIN' or status in ('PINNED', 'JACKKNIFED'):
        if state != 'UNPIN':
            state = 'UNPIN'
            fwd_ticks = 25

        if fwd_ticks > 0:
            fwd_ticks -= 1
            return (12.0, 0.7, look_deg)
        else:
            state = 'REVERSE'

    views = obs.get('views', {})
    rm = views.get('right_mirror', {})
    min_right_y = 999.0

    if rm:
        ox, oy = rm.get('origin', [1.4, -1.35])
        for b_deg, dist in rm.get('walls', []):
            rad = math.radians(b_deg)
            py = oy + dist * math.sin(rad)
            if abs(py) < min_right_y:
                min_right_y = abs(py)

    target_hitch = 0.0
    if min_right_y < 2.0:
        target_hitch = 6.0
    elif min_right_y > 2.8:
        target_hitch = -4.0
    else:
        target_hitch = 2.0

    err = hitch - target_hitch
    steer = err * 2.4
    steer = max(min(steer, 30.0), -30.0)

    speed = -0.4
    return (steer, speed, look_deg)

