# Leg 3 recovery controller: pull forward away from contact, then reverse with proper rail clearance
import math

state = {
    'phase': 'unpin', # 'unpin' (pull fwd to clear rail), then 'reverse'
    'start_prog': None
}

def control(obs):
    look_deg = 170.0
    hitch = obs.get('hitch_deg', 0.0)
    progress = obs.get('progress', {})
    covered = progress.get('covered', 0.0)
    rem = progress.get('remaining', 4.0)
    hold = obs.get('motion', {}).get('hold_s', 0.0)

    if hold > 0:
        return (0.0, 0.0, look_deg)

    if state['phase'] == 'unpin':
        if state['start_prog'] is None:
            state['start_prog'] = covered
        # Pull forward ~1.2m to clear rail and straighten out
        # During contact, trailer rear-left touched rail.
        # Steer slightly to pull trailer away from left rail while going forward:
        # Forward motion: steer left -> vehicle goes left, trailer follows.
        # Steer right (+ -> left, - -> right): steer negative to move forward-right.
        # Also straighten hitch (hitch is -17.7, trailer swung right, so front of trailer is left).
        # When moving forward, hitch naturally decays to 0.
        if covered - state['start_prog'] < -1.2 or covered <= state['start_prog'] - 1.2:
            state['phase'] = 'reverse'
        else:
            # Pull forward
            speed = 0.5
            # steer towards hitch to straighten even faster
            steer = -0.5 * hitch - 10.0
            steer = max(-35.0, min(35.0, steer))
            return (steer, speed, look_deg)

    # Phase: reverse
    speed = -0.35 if rem > 1.8 else -0.2

    # Process visible rails in direct view
    views = obs.get('views', {})
    direct = views.get('direct', {})
    rails = direct.get('walls', [])
    ox, oy = direct.get('origin', [0.1, 0.0])

    y_left_min = None
    y_right_max = None
    for b_deg, d in rails:
        b_rad = math.radians(b_deg)
        px = ox + d * math.cos(b_rad)
        py = oy + d * math.sin(b_rad)
        # Look at rails near and behind rig
        if -4.0 < px < 0.5:
            if py > 0:
                if y_left_min is None or py < y_left_min:
                    y_left_min = py
            else:
                if y_right_max is None or py > y_right_max:
                    y_right_max = py

    target_hitch = 0.0
    if y_left_min is not None and y_right_max is not None:
        corridor_mid = (y_left_min + y_right_max) / 2.0
        # Stay centered
        target_hitch = max(-12.0, min(12.0, corridor_mid * 15.0))
    elif y_left_min is not None:
        # Nominal half corridor ~ 1.5 - 2.0m. If left rail < 1.3m, nudge right (negative hitch)
        if y_left_min < 1.4:
            target_hitch = -10.0 * (1.4 - y_left_min)
    elif y_right_max is not None:
        if y_right_max > -1.4:
            target_hitch = 10.0 * (1.4 + y_right_max)

    # Straighten for final bay entry
    if rem < 1.5:
        target_hitch = 0.0

    hitch_err = hitch - target_hitch
    steer = 2.0 * hitch_err
    steer = max(-40.0, min(40.0, steer))

    return (steer, speed, look_deg)

