state = {
    'phase': 'fwd',
    'start_covered': None
}

def control(obs):
    look_deg = 170.0
    hitch = obs.get('hitch_deg', 0.0)
    progress = obs.get('progress', {})
    covered = progress.get('covered', 0.0)
    rem = progress.get('remaining', 4.0)
    hold = obs.get('motion', {}).get('hold_s', 0.0)

    if hold > 0:
        return (0.0, 0.0, look_deg)

    if state['phase'] == 'fwd':
        if state['start_covered'] is None:
            state['start_covered'] = covered

        # Pull forward 1.2 m straight
        if covered <= state['start_covered'] - 1.2:
            state['phase'] = 'rev_shift'
            state['start_covered'] = None
        else:
            # Move straight forward (0 steer) so front overhang does not swing into left wall
            return (0.0, 0.45, look_deg)

    if state['phase'] == 'rev_shift':
        # Keep trailer swung slightly right (negative hitch ~ -15 to -20 deg) to shift to the right opening
        # until remaining distance is small
        if rem < 2.0:
            state['phase'] = 'rev_straight'
        else:
            target_hitch = -16.0
            hitch_err = hitch - target_hitch
            steer = 2.2 * hitch_err
            steer = max(-40.0, min(40.0, steer))
            return (steer, -0.35, look_deg)

    if state['phase'] == 'rev_straight':
        # Align straight (target_hitch = 0) to enter and satisfy final <= 12 deg condition
        target_hitch = 0.0
        hitch_err = hitch - target_hitch
        steer = 2.2 * hitch_err
        steer = max(-40.0, min(40.0, steer))
        speed = -0.25 if rem > 0.8 else -0.15
        return (steer, speed, look_deg)

    return (0.0, 0.0, look_deg)

