    cam = views.get('camera', None)
    hitch_deg = obs.get('hitch_deg', 0.0)
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)
    look_deg = -41.0

    if hold_s > 0.0:
        return {'steer_deg': 0.0, 'speed_mps': 0.0, 'look_deg': look_deg}

    back_b = 180.0 - hitch_deg
    while back_b > 180: back_b -= 360
    while back_b < -180: back_b += 360

    left_ys = []
    right_ys = []
    far_ys = []
    if cam and 'walls' in cam:
        for b_deg, dist in cam['walls']:
            rel_b = math.radians(b_deg - back_b)
            x = dist * math.cos(rel_b)
            y = dist * math.sin(rel_b)
            if 0.0 < x < 5.0:
                if y > 0:
                    left_ys.append(y)
                else:
                    right_ys.append(-y)
            if 3.0 < x < 10.0:
                far_ys.append(y)

    min_l = min(left_ys) if left_ys else 3.0
    min_r = min(right_ys) if right_ys else 3.0

    clear_l = min_l - 1.28
    clear_r = min_r - 1.28

    if status in ('PINNED', 'JACKKNIFED') or clear_l < 0.1:
        return {'steer_deg': 15.0, 'speed_mps': 1.0, 'look_deg': look_deg}

    des_hitch = -6.0
    if far_ys:
        avg_far = sum(far_ys) / len(far_ys)
        des_hitch += avg_far * 1.5

    if clear_l < 0.8:
        des_hitch -= 15.0 * (0.8 - clear_l)
    elif clear_r < 0.8:
        des_hitch += 15.0 * (0.8 - clear_r)

    des_hitch = max(-20.0, min(15.0, des_hitch))

    hitch_err = hitch_deg - des_hitch
    target_steer = hitch_err * 2.8
    target_steer = max(-35.0, min(35.0, target_steer))

